/*
 * pal_config.h — NuttX feature flags for System.Native PAL
 *
 * Normally generated by CMake from pal_config.h.in.
 * Hand-written for NuttX cross-compilation (Meadow .NET 10 port).
 */

#pragma once

/* ------------------------------------------------------------------ */
/* NuttX target identification                                        */
/* ------------------------------------------------------------------ */
#ifndef TARGET_UNIX
#define TARGET_UNIX 1
#endif


