#define HAVE_IOCTL                  1
#define HAVE_IOCTL_WITH_INT_REQUEST 1
#define HAVE_TIOCGWINSZ             0  /* No terminal window size ioctl */
#define HAVE_PREADV                 0
#define HAVE_PWRITEV                0

